   if(flow)doc+=section('route-table','Étape par étape',plural((r.route||[]).length,' étape',' étapes')+' · de '+money(r.startCash)+' à '+money(r.finalCash),'Chaque étape du parcours, avec ce qu’elle coûte, ce qu’elle rapporte et ce que tu as ensuite.',()=>table([['Quand','Étape','Payé','Reçu','Tu as ensuite'],...(r.route||[]).slice(0,120).map(x=>[hours(x.start/60),x.type==='acquire'?'Achète « '+x.name+' »':x.type==='unlock'?'« '+x.name+' » (une seule fois)':'« '+x.name+' » ×'+x.runs,x.spend?'−'+money(x.spend):'—',x.receive?'+'+money(x.receive):'—',money(x.cashAfter)])],'Le parcours complet'+((r.route||[]).length>120?' (120 premières étapes sur '+r.route.length+')':''),true));
