    const firstBuy=r.purchases.find(x=>x.atSession);if(firstBuy&&firstBuy.atSession>1)thresholds.push('Il te manque <b>'+money(Math.max(0,firstBuy.price+r.input.reserve-r.startCash))+'</b> pour acheter « '+esc(firstBuy.name)+' » dès maintenant.');
