  html+='<div class="b-plan-card-actions">'+btn('Mettre à jour mon plan','data-b-plan-log="1"',true)+(p.log.length?btn('Effacer l’historique','data-b-plan-clear="1"'):'')+'</div><p class="calc-note" id="plan-log-feedback" role="status"></p>';
  if(obs&&obs.last){const L=obs.last,gap=L.gap;
   html+='<div class="b-bilan"><p class="calc-kicker">BILAN DE TA DERNIÈRE PARTIE</p><div class="b-tiles">'+[['Prévu',L.plannedGain===null?'—':signed(L.plannedGain)],['Réel',signed(L.gain)],['Écart',gap===null?'—':(gap>=0.5?'+':gap<=-0.5?'−':'')+money(Math.abs(gap))],['Ton rythme réel',obs.hourly===null?'—':money(Math.round(obs.hourly))+' par heure']].map(([l,v])=>'<span><small>'+esc(l)+'</small><b>'+v+'</b></span>').join('')+'</div><p>'+esc(gap===null?'Le plan repart de ce que tu as maintenant.':Math.abs(gap)<0.5/* lot 5 : un écart nul n’est pas « en avance » */?'Pile comme prévu : le plan repart de ce que tu as.':gap>0?'Tu es en avance : le plan repart de ce que tu as, et il est plus court.':'Tu as gagné moins que prévu : le plan repart de ce que tu as, et la section « Si ça ne se passe pas comme prévu » propose d’autres chemins.')+(obs.sessions>1?' Sur tes '+obs.sessions+' parties notées, tu gagnes en moyenne '+money(obs.perSession)+' par partie.':'')+'</p>'+(p.source==='hourly'&&obs.hourly!==null&&Math.abs(obs.hourly-(si.hourly||0))>1?btn('Adopter mon vrai rythme ('+money(obs.hourly)+' par heure)','data-b-plan-adopt="1"'):'')+'</div>';}
  if(p.log.length){const rows=p.log.slice().reverse().map(e=>{const d=new Date(e.at),date=Number.isFinite(d.getTime())?d.toLocaleDateString('fr-FR',{day:'numeric',month:'short'}):'—';return [date,hours(e.minutes/60),e.plannedGain===null?'—':signed(e.plannedGain),e.gain===null?'—':signed(e.gain),money(e.capital),e.forecast===null?'—':money(e.forecast),Object.keys(e.runs).length?Object.entries(e.runs).filter(([,n])=>n>0).map(([id,n])=>(p.missions.find(m=>m.id===id)?.name||id)+' ×'+n).join(', ')+(e.purchases.length?' · acheté : '+e.purchases.map(id=>p.prerequisites.find(a=>a.id===id)?.name||id).join(', '):''):(e.purchases.length?'acheté : '+e.purchases.map(id=>p.prerequisites.find(a=>a.id===id)?.name||id).join(', '):'—'),e.note||'—'];});
   html+=table([['Date','Joué en tout','Prévu (partie)','Réel (partie)','J’avais','Le plan prévoyait','Fait','Note'],...rows],'Réalisé contre prévu, partie après partie',true)+'<p class="calc-note">« Le plan prévoyait » = l’argent attendu après ce temps de jeu, d’après le plan d’avant la mise à jour. Le plan actuel repart toujours du réel.</p>';}
